<?php
include_once 'global_CDC.php';
include_once 'classes_SP/class_AzureFileSP.php';
include 'dart_init.php';
$currentScript = basename ( $_SERVER ["SCRIPT_NAME"] );

$sigImage = "";

$locID = 'cdcTest';

$filedir = DART_SIG_DIR . $locID;
if (! is_dir ( $filedir )) {
	echo "$filedir : NOT a is_dir";
	if (! mkdir ( $filedir )) {
		echo "$filedir : COULD NOT mkdir";
		exit ();
	} else {
		echo "$filedir : COULD mkdir<br/>";
	}
}
echo "$filedir : IS a is_dir<br/>";

if (! $imgSrc = imagecreatefromstring ( base64_decode ( $sigImage ) )) {
	echo "Could NOT imagecreatefromstring";
	exit ();
}
echo "Could YES imagecreatefromstring<br/>";

$width = imagesx ( $imgSrc );
$height = imagesy ( $imgSrc );

// Make the new image
if (! $imgDest = imagecreatetruecolor ( $width, $height )) {
	echo "Could NOT imagecreatetruecolor";
	exit ();
}
echo "Could YES imagecreatetruecolor<br/>";

// Copy sent into new
if (! imagecopy ( $imgDest, $imgSrc, 0, 0, 0, 0, $width, $height )) {
	echo "Could NOT imagecopy";
	exit ();
}
echo "Could YES imagecopy<br/>";

// Write it out
$file = $filedir . '/' . date ( 'H_i_s' ) . ".png";
if (! imagepng ( $imgDest, $file )) {
	echo "Could NOT imagepng";
	exit ();
}
echo "Could YES imagepng : $file <br/>";

$url = "http://specproddart.azurewebsites.net/azSend.php?i=123456";
$parts = parse_url ( $url );
print_r($parts);
echo "<br/>";

$fp = fsockopen ( $parts ['host'], 80, $errno, $errstr, 30 );
if (! $fp) {
	echo "$url : $errstr ($errno)<br />";
	exit ();
}
echo "$url : Opened<br/>";
$out = "GET /azSend.php?i=123456 HTTP/1.1
Host: specproddart.azurewebsites.net
Content-Length: 0
Connection: Close";
error_log("$currentScript : fwrite() : $out");
fwrite($fp, $out);
fclose ( $fp );
error_log("$currentScript : fclose()");
error_log("$currentScript : shell_exec()");
shell_exec ( 'php azSend.php' . " 123 456 789" . ' > /dev/null 2>&1 &' );
//$output = shell_exec('php azSend.php > /dev/null 2>&1 &');
error_log("$currentScript : exit()");
exit();
?>